examples.setup:
CREATE TABLE invoices (id int PRIMARY KEY);
INSERT INTO invoices SELECT generate_series(1, 3);
CREATE TABLE events (id int PRIMARY KEY, payload text NOT NULL)
  WITH (autovacuum_enabled = off);
INSERT INTO events SELECT g, repeat('x', 100) FROM generate_series(1, 10000) AS g;
CREATE TABLE sizes AS SELECT pg_relation_size('events') AS bytes;

files.examples/01_bloat.sql:
-- Runtime sql-nontx: every statement commits on its own, as in psql.
-- TEMP: only this session sees the table, so no other session's open
-- transaction can hold VACUUM back here (example 2 shows that happening).
CREATE TEMP TABLE counters (id int PRIMARY KEY, hits int NOT NULL, note text NOT NULL);
INSERT INTO counters SELECT g, 0, repeat('x', 100) FROM generate_series(1, 10000) AS g;

CREATE TABLE sizes (n int GENERATED ALWAYS AS IDENTITY, step text, bytes bigint);
INSERT INTO sizes (step, bytes) VALUES ('10000 rows loaded', pg_relation_size('counters'));

UPDATE counters SET hits = hits + 1;
INSERT INTO sizes (step, bytes) VALUES ('UPDATE every row', pg_relation_size('counters'));
VACUUM counters;
INSERT INTO sizes (step, bytes) VALUES ('VACUUM', pg_relation_size('counters'));
UPDATE counters SET hits = hits + 1;
INSERT INTO sizes (step, bytes) VALUES ('UPDATE every row again', pg_relation_size('counters'));
DELETE FROM counters WHERE id % 2 = 0;
INSERT INTO sizes (step, bytes) VALUES ('DELETE every other row', pg_relation_size('counters'));
VACUUM counters;
INSERT INTO sizes (step, bytes) VALUES ('VACUUM', pg_relation_size('counters'));
VACUUM FULL counters;
INSERT INTO sizes (step, bytes) VALUES ('VACUUM FULL', pg_relation_size('counters'));

-- Byte counts depend on the build; the ratio to the first one doesn't.
SELECT n, step,
       round(bytes::numeric / first_value(bytes) OVER (ORDER BY n), 1) AS size_vs_loaded
FROM sizes ORDER BY n;

files.examples/02_long_transaction.sql:
-- A: a long report. It reads invoices and never touches events.
A: BEGIN ISOLATION LEVEL REPEATABLE READ;
A: SELECT count(*) AS invoices FROM invoices;

-- B: delete the newer half of events, then vacuum. Those rows fill the
-- last pages, so a successful VACUUM would hand those pages back.
B: DELETE FROM events WHERE id > 5000;
B: VACUUM events;
B: SELECT pg_relation_size('events') < (SELECT bytes FROM sizes) AS shrank;

-- A's snapshot is older than the delete: for A those rows still exist,
-- so VACUUM had to keep them. End the report and try again.
A: COMMIT;
B: VACUUM events;
B: SELECT pg_relation_size('events') < (SELECT bytes FROM sizes) AS shrank;

files.examples/03_hot_fillfactor.sql:
-- The same 10000 rows and the same updates, in two tables: one packed full
-- (the default fillfactor, 100), one that leaves half of every page free.
CREATE TEMP TABLE packed (id int PRIMARY KEY, hits int NOT NULL, note text NOT NULL);
CREATE TEMP TABLE roomy (id int PRIMARY KEY, hits int NOT NULL, note text NOT NULL)
  WITH (fillfactor = 50);
INSERT INTO packed SELECT g, 0, repeat('x', 100) FROM generate_series(1, 10000) AS g;
INSERT INTO roomy SELECT * FROM packed;
CREATE TABLE sizes AS
  SELECT pg_relation_size('packed') AS packed, pg_relation_size('roomy') AS roomy;

-- hits has no index, so an update that finds room on its own page is HOT.
-- No VACUUM anywhere below.
UPDATE packed SET hits = hits + 1;
UPDATE packed SET hits = hits + 1;
UPDATE packed SET hits = hits + 1;
UPDATE roomy SET hits = hits + 1;
UPDATE roomy SET hits = hits + 1;
UPDATE roomy SET hits = hits + 1;

SELECT round(pg_relation_size('packed')::numeric / packed, 1) AS packed_growth,
       round(pg_relation_size('roomy')::numeric / roomy, 1) AS roomy_growth,
       round(roomy::numeric / packed, 1) AS roomy_start_vs_packed
FROM sizes;
